describe('Assign Category to Record via Dropdown', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="login-username"]').type('testuser');
    cy.get('[data-testid="login-password"]').type('password123');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="records-menu"]').click();
    cy.get('[data-testid="record-item-1"]').click();
  });

  it('should successfully assign a category to a record', () => {
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option-electronics"]').click();
    cy.get('[data-testid="save-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Category assigned successfully');
    cy.get('[data-testid="category-display"]').should('contain', 'Electronics');
  });

  it('should handle category change from one category to another', () => {
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option-furniture"]').click();
    cy.get('[data-testid="save-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option-books"]').click();
    cy.get('[data-testid="save-button"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="category-display"]').should('contain', 'Books');
  });

  it('should display all available categories in dropdown', () => {
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-option-electronics"]').should('be.visible');
    cy.get('[data-testid="category-option-furniture"]').should('be.visible');
    cy.get('[data-testid="category-option-books"]').should('be.visible');
    cy.get('[data-testid="category-option-clothing"]').should('be.visible');
  });

  it('should require category selection before saving', () => {
    cy.get('[data-testid="category-dropdown"]').should('have.value', '');
    cy.get('[data-testid="save-button"]').click();
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select a category');
  });

  it('should close dropdown when category is selected', () => {
    cy.get('[data-testid="category-dropdown"]').click();
    cy.get('[data-testid="category-dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="category-option-electronics"]').click();
    cy.get('[data-testid="category-dropdown-menu"]').should('not.be.visible');
  });
});
